}
void main(){
 float depth=texture(uDepth,uv).r;
 vec3 c;
 if(depth>=.999999){
 vec3 ray=normalize(uCameraForward+uCameraRight*((uv.x*2.0-1.0)/uProjectionScale.x)+uCameraUp*((uv.y*2.0-1.0)/uProjectionScale.y));
